//! `pve_dungeon_content` — Production wiki PvE dungeon content loader (`schema_version = 2`).
//!
//! Reads compact runtime content generated by `tools/import_wiki_pve.py` from
//! `data/wiki_pve_content.json` (or `EVOMU_WIKI_PVE_CONTENT_PATH`).
//!
//! # Data Provenance Notice
//! - **EVE University Wiki (`CC BY-SA 4.0`, local gitignored export):** Authoritative room
//!   progression, wave compositions, wave trigger graphs, distance metadata, and concrete NPC
//!   `type_ids` (`resolution.type_ids` / `candidate_type_ids`).
//! - **Deterministic SDE Stand-In (`sde.npc_spawn_groups`):** When a wiki NPC row omits concrete
//!   ship `type_ids` (`partly_resolved` / `unresolved`) but carries a recognized ship class and
//!   faction, a deterministic combat NPC stand-in is selected from SDE spawn groups excluding
//!   non-combatant props and invulnerable CONCORD/police groups.
//! - **SDE Synthetic Fallback (`build_sde_deadspace_rooms`):** Used ONLY when no authored wiki
//!   entry matches the target `DungeonTemplateId` / dungeon name.

#![forbid(unsafe_code)]

use crate::router::ServerContext;
use crate::services::combat_crimewatch::combat_legacy_ess::{
    is_invulnerable_npc_authority_group, is_non_combat_npc_prop_group,
    is_sleeper_or_drifter_npc_group,
};
use eve_db::service_domains::{
    DungeonNpcGroup, DungeonRuntimeObject, DungeonRuntimeRoom, DungeonTemplateId,
    DungeonTrigger, DungeonTriggerAction, DungeonTriggerKind,
};
use serde::Deserialize;
use std::collections::{BTreeMap, HashMap, HashSet};
use std::path::Path;
use std::sync::Arc;

pub const WIKI_PVE_SCHEMA_VERSION: u32 = 2;
pub const WIKI_PVE_CONTENT_ENV_VAR: &str = "EVOMU_WIKI_PVE_CONTENT_PATH";
pub const DEFAULT_WIKI_PVE_CONTENT_PATH: &str = "data/wiki_pve_content.json";

